// Adapted from the owner's five-stage quadratic presentation.
// Fractions keep every algebraic identity exact; SVG coordinates are numerical.
const gcd=(a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b){[a,b]=[b,a%b];}return a||1n;};
export function fraction(n,d=1n){n=BigInt(n);d=BigInt(d);if(!d)throw new RangeError('Zero denominator');if(d<0n){n=-n;d=-d;}const g=gcd(n,d);return {n:n/g,d:d/g};}
export function decimalFraction(value){const s=String(value).trim();if(!/^[+-]?(?:\d+(?:\.\d{0,9})?|\.\d{1,9})$/.test(s))throw new RangeError('Use a finite decimal with at most nine decimal places');const neg=s.startsWith('-'),raw=s.replace(/^[+-]/,'').split('.');const d=10n**BigInt((raw[1]||'').length);return fraction((neg?-1n:1n)*BigInt((raw[0]||'0')+(raw[1]||'')),d);}
const add=(a,b)=>fraction(a.n*b.d+b.n*a.d,a.d*b.d),neg=a=>fraction(-a.n,a.d),sub=(a,b)=>add(a,neg(b)),mul=(a,b)=>fraction(a.n*b.n,a.d*b.d),div=(a,b)=>fraction(a.n*b.d,a.d*b.n),num=a=>Number(a.n)/Number(a.d),F=x=>fraction(x);
export function quadraticModel(a,b,c){a=typeof a==='object'?a:decimalFraction(a);b=typeof b==='object'?b:decimalFraction(b);c=typeof c==='object'?c:decimalFraction(c);if(!a.n)throw new RangeError('A quadratic requires a ≠ 0');const D=sub(mul(b,b),mul(F(4),mul(a,c))),alpha=div(neg(b),mul(F(2),a)),beta=sub(c,div(mul(b,b),mul(F(4),a)));let roots=[];if(D.n===0n)roots=[num(alpha)];else if(D.n>0n){const av=num(a),bv=num(b),cv=num(c),q=-.5*(bv+(bv<0?-1:1)*Math.sqrt(num(D)));roots=[q/av,cv/q].sort((x,y)=>x-y);}return {a,b,c,D,alpha,beta,roots,case:D.n>0n?1:D.n===0n?0:-1};}
export function coefficientsFromMode(mode,values){const [a,u,v]=values.map(x=>typeof x==='object'?x:decimalFraction(x));if(!a.n)throw new RangeError('a ≠ 0');return mode==='canonical'?[a,mul(F(-2),mul(a,u)),add(mul(a,mul(u,u)),v)]:mode==='roots'?[a,neg(mul(a,add(u,v))),mul(a,mul(u,v))]:[a,u,v];}
export function signAt(model,x){const [a,b,c]=[model.a,model.b,model.c].map(num);const y=(a*x+b)*x+c;return y===0?0:y>0?1:-1;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mi=s=>/^x[012₀₁₂]$/.test(s)?`<msub><mi>x</mi><mn>${({'₀':'0','₁':'1','₂':'2'})[s[1]]||s[1]}</mn></msub>`:`<mi>${esc(s)}</mi>`,mn=s=>`<mn>${esc(s)}</mn>`,mo=s=>`<mo>${esc(s)}</mo>`,row=s=>`<mrow>${s}</mrow>`,sq=s=>`<msup>${row(s)}${mn(2)}</msup>`,frac=(a,b)=>`<mfrac>${row(a)}${row(b)}</mfrac>`;
const fm=f=>f.d===1n?mn(f.n):frac(mn(f.n),mn(f.d)),br=s=>row(mo('(')+s+mo(')'));
const math=s=>`<math xmlns="http://www.w3.org/1998/Math/MathML">${row(s)}</math>`;
const fmt=(x,lang)=>new Intl.NumberFormat(lang,{maximumFractionDigits:5}).format(Object.is(x,-0)?0:x);
const signed=(f,term='')=>f.n===0n?'':mo(f.n<0n?'−':'+')+(term&& (f.n===f.d||f.n===-f.d)?'':fm(fraction(f.n<0n?-f.n:f.n,f.d)))+term;
const coeff=(a,term)=> (a.n<0n?mo('−'):'')+(a.n===a.d||a.n===-a.d?'':fm(fraction(a.n<0n?-a.n:a.n,a.d)))+term;
const poly=m=>coeff(m.a,sq(mi('x')))+signed(m.b,mi('x'))+signed(m.c);
function rootExpression(m,i){if(m.case===0)return fm(m.alpha);const sign=(num(m.a)>0?i===0:i===1)?'−':'+';return frac(fm(neg(m.b))+mo(sign)+`<msqrt>${fm(m.D)}</msqrt>`,fm(mul(F(2),m.a)));}
const titles=[['Forme développée','Expanded form'],['Forme canonique et variations','Vertex form and variation'],['Discriminant','Discriminant'],['Racines et factorisation','Roots and factorisation'],['Signe du trinôme','Sign of the quadratic']];
const langToken=t=>t(['','-en']);
export function workshopMarkup(t){return `<main id="main" class="page quadratic-workshop" tabindex="-1"><a href="#lab/quadratic">${t(['Laboratoire des paraboles','Parabola lab'])}</a><div class="lab-heading"><div><span class="eyebrow">${t(['Présenter et explorer','Present and explore'])}</span><h1>${t(['Trinôme du second degré','Quadratic polynomials'])}</h1><p>${t(['Choisis une étape, puis fais varier les paramètres. Les expressions sont exactes ; le graphique et les décimales sont approchés.','Choose a stage, then vary the parameters. Expressions are exact; the graph and decimal values are approximate.'])}</p></div><span class="level">${t(['Première spécialité','Upper high school'])}</span></div><nav class="quadratic-stages" aria-label="${t(['Étapes du raisonnement','Reasoning stages'])}">${titles.map((title,i)=>`<button data-q-stage="${i+1}" aria-pressed="${i===0}">${i+1} · ${t(title)}</button>`).join('')}</nav><div class="quadratic-layout"><section class="quadratic-panel"><div id="quadratic-explanation" aria-live="polite"></div><div class="story-controls"><button data-q-previous>${t(['Précédent','Previous'])}</button><span id="quadratic-step"></span><button data-q-next>${t(['Suivant','Next'])}</button><button data-q-all aria-pressed="false">${t(['Tout afficher','Show all'])}</button></div><details><summary>${t(['Avant de commencer','Before you begin'])}</summary><p>${t(['On étudie f sur ℝ, avec a ≠ 0. Développer, factoriser et lire un repère sont les prérequis. Le discriminant et le signe général du trinôme relèvent de la Première spécialité.','We study f on ℝ, with a ≠ 0. Prerequisites: expanding, factorising and reading coordinate axes. The discriminant and the general sign rule are upper high school topics.'])}</p></details></section><section class="quadratic-panel"><div id="quadratic-graph"></div><p id="quadratic-graph-caption"></p><label for="quadratic-mode">${t(['Paramètres','Parameters'])}</label><select id="quadratic-mode"><option value="expanded">a, b, c</option><option value="canonical">a, α, β</option><option value="roots">a, x₁, x₂</option></select><div id="quadratic-inputs"></div><p id="quadratic-error" role="status"></p><div class="quadratic-presets">${[[2,-4,-6],[2,-4,2],[2,-4,4],[-2,4,6],[-2,4,-2],[-2,4,-4]].map((v,i)=>`<button data-q-preset="${i}">${i<3?'a > 0':'a < 0'} · Δ ${['>','=','<'][i%3]} 0</button>`).join('')}</div><p class="muted">${t(['Changer de mode conserve le trinôme. Modifier des paramètres décimaux dans le mode racines définit un nouveau trinôme.','Switching mode preserves the polynomial. Editing decimal parameters in root mode defines a new polynomial.'])}</p></section></div><details class="quadratic-practice"><summary>${t(['Chercher et justifier','Investigate and justify'])}</summary><p>${t(['Pourquoi le signe de a détermine-t-il l’ouverture de la parabole ? Trouve un exemple pour chacun des trois signes de Δ. Pour f(x)=2x²−4x−6, résous f(x) ≤ 0 puis justifie la réponse sans utiliser le dessin.','Why does the sign of a determine the opening of the parabola? Find an example for each of the three signs of Δ. For f(x)=2x²−4x−6, solve f(x) ≤ 0 and justify without relying on the drawing.'])}</p><details><summary>${t(['Comparer avec une justification','Compare with a justification'])}</summary><p>${t(['2x²−4x−6=2(x+1)(x−3). Les racines sont −1 et 3. Comme a=2>0, le produit est négatif entre les racines et nul aux racines : l’ensemble des solutions est [−1 ; 3].','2x²−4x−6=2(x+1)(x−3). Roots are −1 and 3. Since a=2>0, the product is negative between the roots and zero at the roots: the solution set is [−1,3].'])}</p></details></details><p><a class="secondary" href="./resources/quadratic-presentation${langToken(t)}.pdf" download>${t(["Télécharger la fiche · PDF","Download the study sheet · PDF"])}</a></p><p><a href="#library/@quadratic">${t(['Cours, exercices et corrigés du chapitre','Topic notes, exercises and worked solutions'])}</a></p></main>`;}
export function explanation(m,stage,t,lang){const fx=mi('f')+br(mi('x')),eq=mo('='),al=fm(m.alpha),be=fm(m.beta),r=m.roots;const approx=(label,v)=>`<p>${esc(label)} ≈ ${esc(fmt(v,lang))}</p>`;let body='';
 if(stage===1)body=math(fx+eq+poly(m))+`<p>${math(mi('a')+eq+fm(m.a)+mo(',')+mi('b')+eq+fm(m.b)+mo(',')+mi('c')+eq+fm(m.c))}</p>`;
 if(stage===2)body=math(fx+eq+coeff(m.a,sq(br(mi('x')+mo('−')+br(al))))+signed(m.beta))+`<p>${math(mi('α')+eq+frac(mo('−')+mi('b'),mn(2)+mi('a'))+eq+al)}</p><p>${math(mi('β')+eq+mi('f')+br(mi('α'))+eq+be)}</p><p>${t(num(m.a)>0?['f décroît jusqu’à α, puis croît. Son minimum est β, atteint en α.','f decreases up to α, then increases. Its minimum is β, attained at α.']:['f croît jusqu’à α, puis décroît. Son maximum est β, atteint en α.','f increases up to α, then decreases. Its maximum is β, attained at α.'])}</p>`;
 if(stage===3)body=math(mi('Δ')+eq+sq(mi('b'))+mo('−')+mn(4)+mi('a')+mi('c')+eq+fm(m.D))+`<p>${t(m.case>0?['Deux racines réelles distinctes.','Two distinct real roots.']:m.case===0?['Une racine réelle double.','One double real root.']:['Aucune racine réelle.','No real roots.'])}</p>`;
 if(stage===4){if(m.case<0)body=`<p>${t(['Aucune racine réelle : aucune factorisation en facteurs du premier degré à coefficients réels.','No real roots: no factorisation into linear factors with real coefficients.'])}</p>`;else if(m.case===0)body=math(mi('x₀')+eq+rootExpression(m,0))+`<p>${math(fx+eq+coeff(m.a,sq(br(mi('x')+mo('−')+mi('x₀')))))}</p>`;else body=r.map((x,i)=>`<p>${math(mi('x'+(i+1))+eq+rootExpression(m,i))}</p>`+approx('x'+(i+1),x)).join('')+`<p>${math(fx+eq+coeff(m.a,br(mi('x')+mo('−')+mi('x₁'))+br(mi('x')+mo('−')+mi('x₂'))))}</p><p>${math(mi('x₁')+mo('+')+mi('x₂')+eq+frac(mo('−')+mi('b'),mi('a'))+eq+fm(div(neg(m.b),m.a)))}</p><p>${math(mi('x₁')+mi('x₂')+eq+frac(mi('c'),mi('a'))+eq+fm(div(m.c,m.a)))}</p>`;}
 if(stage===5){const s=num(m.a)>0?'+':'−',op=s==='+'?'−':'+';let top=['−∞'],bottom=[];if(m.case>0){top.push('', 'x₁','','x₂','','+∞');bottom=['',s,'0',op,'0',s,''];}else if(m.case===0){top.push('','x₀','','+∞');bottom=['',s,'0',s,''];}else {top.push('','+∞');bottom=['',s,''];}body=`<div class="quadratic-sign-scroll"><table class="quadratic-sign"><caption>${t(['Tableau de signes (racines exactes définies à l’étape 4)','Sign table (exact roots defined at stage 4)'])}</caption><tbody><tr><th scope="row">x</th>${top.map(v=>`<td>${v}</td>`).join('')}</tr><tr><th scope="row">f(x)</th>${bottom.map(v=>`<td>${v}</td>`).join('')}</tr></tbody></table></div><p>${t(m.case>0?['Le trinôme est du signe de a à l’extérieur des racines, du signe opposé entre elles, et nul aux racines.','The polynomial has the sign of a outside the roots, the opposite sign between them, and is zero at the roots.']:m.case===0?['Le trinôme est du signe de a, sauf à la racine double où il est nul.','The polynomial has the sign of a except at the double root, where it is zero.']:['Le trinôme est strictement du signe de a sur ℝ.','The polynomial has strictly the sign of a throughout ℝ.'])}</p>`;}
 return `<section><h2>${stage} · ${t(titles[stage-1])}</h2>${body}</section>`;
}
export function graph(m,stage,t,lang){const [a,b,c]=[m.a,m.b,m.c].map(num),al=num(m.alpha),be=num(m.beta);const xmin=Math.min(-6,al-3,...m.roots.map(x=>x-1)),xmax=Math.max(6,al+3,...m.roots.map(x=>x+1));const ymin=Math.min(-12,be-3),ymax=Math.max(12,be+3);const X=x=>55+(x-xmin)*590/(xmax-xmin),Y=y=>340-(y-ymin)*300/(ymax-ymin);const line=(x,y,u,v,cls)=>`<line x1="${X(x)}" y1="${Y(y)}" x2="${X(u)}" y2="${Y(v)}" class="${cls}"/>`;let grid='';for(let i=0;i<=6;i++){const x=xmin+(xmax-xmin)*i/6,y=ymin+(ymax-ymin)*i/6;grid+=line(x,ymin,x,ymax,'q-grid')+line(xmin,y,xmax,y,'q-grid')+`<text x="${X(x)}" y="365" text-anchor="middle">${esc(fmt(x,lang))}</text><text x="48" y="${Y(y)+5}" text-anchor="end">${esc(fmt(y,lang))}</text>`;}let d='';for(let i=0;i<=240;i++){const x=xmin+(xmax-xmin)*i/240;d+=(i?'L':'M')+X(x)+','+Y((a*x+b)*x+c);}let shading='';if(stage>=5){const points=[xmin,...m.roots.filter(x=>x>xmin&&x<xmax),xmax];for(let i=0;i<points.length-1;i++)shading+=`<rect x="${X(points[i])}" y="40" width="${X(points[i+1])-X(points[i])}" height="300" class="${signAt(m,(points[i]+points[i+1])/2)>0?'q-positive':'q-negative'}"/>`;}
 const point=(x,y,cls)=>`<circle cx="${X(x)}" cy="${Y(y)}" r="6" class="${cls}"/>`;
return `<svg viewBox="0 0 700 390" role="img" aria-label="${esc(t(['Parabole et repères de l’étape sélectionnée','Parabola and markers for the selected stage']))}"><title>${esc(t(['Graphique approché du trinôme','Approximate graph of the polynomial']))}</title><defs><clipPath id="quadratic-clip"><rect x="55" y="40" width="590" height="300"/></clipPath></defs><g>${grid}</g><g clip-path="url(#quadratic-clip)">${shading}${line(xmin,0,xmax,0,'q-axis')}${line(0,ymin,0,ymax,'q-axis')}<path d="${d}" class="q-curve"/>${stage>=2?line(al,ymin,al,ymax,'q-symmetry')+point(al,be,'q-vertex'):''}${stage>=4?m.roots.map(x=>point(x,0,'q-root')).join(''):''}</g><text x="660" y="${Y(0)-8}">x</text><text x="${X(0)+10}" y="30">y</text></svg>`;
}
const workshopState={coefficients:['2','-4','-6'].map(decimalFraction),mode:'expanded',stage:1,all:false};
export function bindWorkshop(root,t,lang){const $=s=>root.querySelector(s),state=workshopState;let model;
 function inputs(){model=quadraticModel(...state.coefficients);const values=state.mode==='canonical'?[model.a,model.alpha,model.beta].map(num):state.mode==='roots'?[num(model.a),model.roots[0],model.roots.at(-1)]:state.coefficients.map(num);const labels=state.mode==='canonical'?['a','α','β']:state.mode==='roots'?['a','x₁','x₂']:['a','b','c'];$('#quadratic-inputs').innerHTML=values.map((v,i)=>`<label for="quadratic-value-${i}">${labels[i]}<input id="quadratic-value-${i}" data-q-input="${i}" type="number" step="any" min="-1000" max="1000" value="${Number(v.toFixed(9))}" inputmode="decimal"><input data-q-slider="${i}" type="range" aria-label="${labels[i]}" min="${Math.min(-4,Math.floor(v))}" max="${Math.max(4,Math.ceil(v))}" step="0.25" value="${v}"></label>`).join('');$('#quadratic-mode').value=state.mode;$('#quadratic-mode option[value="roots"]').disabled=model.case<0;}
 function paint(){model=quadraticModel(...state.coefficients);$('#quadratic-mode option[value="roots"]').disabled=model.case<0;$('#quadratic-explanation').innerHTML=(state.all?[1,2,3,4,5]:[state.stage]).map(s=>explanation(model,s,t,lang)).join('');$('#quadratic-graph').innerHTML=graph(model,state.all?5:state.stage,t,lang);$('#quadratic-graph-caption').textContent=t(['Repère gradué ; sommet et racines sont inclus dans la fenêtre. Les couleurs du signe complètent le tableau.','Graduated axes; vertex and roots are included in the window. Sign colours complement the table.']);$('#quadratic-step').textContent=`${state.stage} / 5`;root.querySelectorAll('[data-q-stage]').forEach(b=>b.setAttribute('aria-pressed',String(!state.all&&Number(b.dataset.qStage)===state.stage)));$('[data-q-all]').setAttribute('aria-pressed',String(state.all));$('[data-q-previous]').disabled=state.stage===1;$('[data-q-next]').disabled=state.stage===5;}
 function go(n){state.stage=n;state.all=false;paint();}
 root.querySelectorAll('[data-q-stage]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.qStage))));$('[data-q-previous]').addEventListener('click',()=>go(Math.max(1,state.stage-1)));$('[data-q-next]').addEventListener('click',()=>go(Math.min(5,state.stage+1)));$('[data-q-all]').addEventListener('click',()=>{state.all=!state.all;paint();});
 $('#quadratic-mode').addEventListener('change',e=>{if(e.target.value==='roots'&&quadraticModel(...state.coefficients).case<0){e.target.value=state.mode;return;}state.mode=e.target.value;inputs();paint();});
 const commitInputs=()=>{try{const values=[...root.querySelectorAll('[data-q-input]')].map(e=>e.value);if(values.some(v=>!v||!Number.isFinite(Number(v))||Math.abs(Number(v))>1000))throw Error('range');state.coefficients=coefficientsFromMode(state.mode,values);$('#quadratic-error').textContent='';paint();}catch{$('#quadratic-error').textContent=t(['Valeurs entre −1000 et 1000, au plus neuf décimales, avec a ≠ 0. Le dernier trinôme valide reste affiché.','Use values between −1000 and 1000, at most nine decimal places, with a ≠ 0. The last valid polynomial remains displayed.']);}};
 $('#quadratic-inputs').addEventListener('change',e=>{if(e.target.matches('[data-q-input]'))commitInputs();});
 $('#quadratic-inputs').addEventListener('input',e=>{if(!e.target.matches('[data-q-slider]'))return;root.querySelector(`[data-q-input="${e.target.dataset.qSlider}"]`).value=e.target.value;commitInputs();});
 root.querySelectorAll('[data-q-preset]').forEach(b=>b.addEventListener('click',()=>{state.coefficients=[[2,-4,-6],[2,-4,2],[2,-4,4],[-2,4,6],[-2,4,-2],[-2,4,-4]][Number(b.dataset.qPreset)].map(decimalFraction);if(state.mode==='roots'&&quadraticModel(...state.coefficients).case<0)state.mode='expanded';$('#quadratic-error').textContent='';inputs();paint();}));inputs();paint();return ()=>{};
}
